/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"ableton-level-4","number":4,"title":"Arrangement View","skillBand":"Textbook","duration":"From the course textbook","summary":"- Gate ID: ableton-gate-b - Prerequisites: Module 3 (Sections 3.1–3.4) and Module 4 (Sections 4.1–4.2)","modules":[{"id":"ableton-m-GB-1","code":"GB","title":"Readiness Assessment: Gate B","blurb":"- Gate ID: ableton-gate-b - Prerequisites: Module 3 (Sections 3.1–3.4) and Module 4 (Sections 4.1–4.2)","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-gate-b","title":"Section overview","blocks":[{"type":"step","title":"Non-Linear to Linear Structural Composition","blocks":[{"type":"heading","text":"Assessment Overview","level":3},{"type":"list","items":["<strong>Gate ID:</strong> <code>ableton-gate-b</code>","<strong>Prerequisites:</strong> Module 3 (Sections 3.1–3.4) and Module 4 (Sections 4.1–4.2)","<strong>Evaluation Format:</strong> Deterministic Self-Assessment Protocol (Direct execution in Ableton Live 12 Standard)","<strong>Objective:</strong> Verify operational fluency in non-linear Session improvisation, real-time timeline printing, timeline structural navigation, linked-track editing, and global time manipulation."],"ordered":false},{"type":"heading","text":"Verification Drill Protocol","level":3},{"type":"prose","html":"Execute the following four operational drills in Ableton Live 12 Standard:"},{"type":"heading","text":"Drill 1: Constructing the 8-Scene Session Sketch","level":4},{"type":"list","items":["In Session View, construct a multi-track sketch across at least 4 tracks (Drums, Bass, Chords, Lead).","Create 8 complete Scenes named sequentially:","<code>1-Intro</code>, <code>2-Verse A</code>, <code>3-Verse B</code>, <code>4-Pre-Chorus</code>, <code>5-Chorus</code>, <code>6-Bridge</code>, <code>7-Solo</code>, <code>8-Outro</code>.","In at least two empty clip slots, remove the Clip Stop button (<code>Ctrl+E</code>) to enable continuous sustaining playback across scene transitions.","In at least two clips, configure <strong>Follow Actions</strong> to create an automated 4-bar fill cycle that returns automatically to the main groove."],"ordered":true},{"type":"heading","text":"Drill 2: Real-Time Performance Printing Pass","level":4},{"type":"list","items":["Arm Global Arrangement Recording (<code>F9</code>).","Improvise a continuous 60 to 90-second song progression by launching scenes from <code>1-Intro</code> through <code>8-Outro</code>.","During playback of Scene 5 (Chorus), execute a live manual filter sweep on an instrument device.","Stop recording (<code>Spacebar</code>)."],"ordered":true},{"type":"heading","text":"Drill 3: Timeline Navigation & Structural Labeling","level":4},{"type":"list","items":["Switch to Arrangement View (<code>Tab</code>).","Insert structural <strong>Locators</strong> at each major section boundary (<code>Intro</code>, <code>Verse</code>, <code>Chorus</code>, <code>Bridge</code>, <code>Outro</code>).","Set the <strong>Arrangement Loop Brace</strong> (<code>Ctrl+L</code>) around the 8-bar Chorus section.","Execute smooth, click-free fades on all audio clip boundaries."],"ordered":true},{"type":"heading","text":"Drill 4: Global Time Editing & Linked-Track Manipulation","level":4},{"type":"list","items":["Select the 8-bar Chorus section across all tracks.","Execute <strong>Duplicate Time</strong> (<code>Ctrl+Shift+D</code>) to create an immediate double-chorus.","Link Track 1 (Drums) and Track 2 (Bass) via <strong>Link Tracks</strong> (<code>🔗</code>).","Select 2 bars of time across the linked group and execute a split (<code>Ctrl+E</code>). Confirm that both tracks split simultaneously at the exact same sample position.","Unlink tracks when complete."],"ordered":true}]}],"minutes":8},{"id":"ableton-gate-b-2","title":"B Verification Checklist & Sign-Off","blocks":[{"type":"step","title":"B Verification Checklist & Sign-Off","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[GATE B PASS CRITERIA]\n[ ] Drill 1 Complete: 8-scene Session matrix constructed with custom stop buttons and Follow Actions.\n[ ] Drill 2 Complete: Real-time Session performance printed to Arrangement timeline with automation.\n[ ] Drill 3 Complete: Section locators placed, loop brace set, and audio fades applied.\n[ ] Drill 4 Complete: Duplicate Time (Ctrl+Shift+D) and Linked-Track Editing successfully executed.</pre>"},{"type":"prose","html":"<strong>Status:</strong> When all criteria are checked, the student is certified for Module 5: Clips, Warp &amp; Tempo."}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-4-1-2","code":"4.1","title":"Arrangement View as a Timeline","blurb":"- Section ID: ableton-sec-4-1 - Lessons Included: ableton-l4-1-1, ableton-l4-1-2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l4-1-1","title":"Section overview","blocks":[{"type":"step","title":"Section 4.1 — Timeline Literacy, Navigation & Clip Geometry","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-4-1</code>","<strong>Lessons Included:</strong> <code>ableton-l4-1-1</code>, <code>ableton-l4-1-2</code>","<strong>Target Skill Band:</strong> Linear DAW Operator &amp; Timeline Editor","<strong>Manual Spine References:</strong> Chapter 6 (<em>Arrangement View: 6.1–6.10</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard Linear Timeline Engine"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Navigate the Arrangement Ruler &amp; Grid:</strong> Master horizontal/vertical zooming protocols, scrub area auditioning, playhead placement, and the Follow Playhead toggle (<code>F</code>).","<strong>Implement Structural Locators &amp; Loop Braces:</strong> Insert, rename, and jump to section <strong>Locators</strong>, and set the <strong>Arrangement Loop Brace</strong> (<code>Ctrl+L</code>) for iterative section editing.","<strong>Program Timeline Meter Changes:</strong> Insert and automate time signature changes along the Arrangement beat ruler.","<strong>Manipulate Timeline Clip Geometry:</strong> Move, slip, trim, duplicate (<code>Ctrl+D</code>), split (<code>Ctrl+E</code>), and crossfade audio clip boundaries to prevent boundary clicks.","<strong>Configure the Adaptive vs. Fixed Editing Grid:</strong> Switch grid snapping modes (<code>Ctrl+1</code>, <code>Ctrl+2</code>, <code>Ctrl+3</code>, <code>Ctrl+4</code>) to manipulate audio events with sample-accurate or grid-quantized precision."],"ordered":true}]}],"minutes":8},{"id":"ableton-l4-1-1-2","title":"4.1.1: Navigation, Locators, Transport & Loop Braces","blocks":[{"type":"step","title":"1.1 The Arrangement View Topology","blocks":[{"type":"prose","html":"Arrangement View lays out the song structure horizontally along a global chronological time ruler:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                        ARRANGEMENT VIEW TOPOLOGY                            │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  BEAT RULER:  [1.1]         [9.1]         [17.1]        [25.1]       [33.1] │\n│  LOCATORS:    ▼ \"Intro\"     ▼ \"Verse\"     ▼ \"Chorus\"    ▼ \"Bridge\"   ▼ \"Out\"│\n│  LOOP BRACE:  [===========================] (Bars 9.1 to 25.1)              │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  Track 1 (Kick)  │[===Clip===][===Clip===][===Clip===][===Clip===]│ Vol: 0dB│\n│  Track 2 (Snare) │            [===Clip===][===Clip===]            │ Vol:-3dB│\n│  Track 3 (Bass)  │[=======Clip===========][=======Clip===========]│ Vol:-6dB│\n│  Track 4 (Synth) │[===================Clip=======================]│ Vol:-4dB│\n├─────────────────────────────────────────────────────────────────────────────┤\n│  STATUS / INFO:  Follow: [ON] │ Grid: 1/16 │ Time: 1:12.400 │ In/Out Config │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"1.2 Zooming & Scrubbing Mechanics","blocks":[{"type":"list","items":["<strong>Horizontal Zoom:</strong> Drag vertically in the Beat Ruler (magnifying glass cursor), or use keyboard shortcuts <code>+</code> (zoom in) and <code>-</code> (zoom out).","<strong>Vertical Track Height Zoom:</strong> Drag the bottom border of any track header, or press <code>Alt +</code> / <code>Alt -</code> to scale all track heights simultaneously.","<strong>Zoom to Selection:</strong> Select any time range or clip and press <code>Z</code> to fit the selection to the window; press <code>Shift+Z</code> to zoom back out to the full song overview.","<strong>Scrubbing Audio:</strong> Hover the mouse in the lower half of the Beat Ruler (speaker icon appears) and click to initiate immediate playback from that exact time point.","<strong>Follow Playhead (<code>F</code>):</strong> When enabled, the view auto-scrolls to keep the active playhead visible during playback."],"ordered":false}]},{"type":"step","title":"1.3 Locators & Arrangement Loop Braces","blocks":[{"type":"list","items":["<strong>Adding Locators:</strong> Right-click the Beat Ruler and select <em>Add Locator</em> (or click the <strong>Set</strong> button in the Control Bar). Rename locators (<code>Ctrl+R</code>) to delineate song sections (<code>Intro</code>, <code>Verse 1</code>, <code>Chorus</code>, <code>Solo</code>).","<strong>Jumping Between Locators:</strong> Press the <code>&lt;</code> and <code>&gt;</code> buttons in the Control Bar or assign Key/MIDI mappings to jump instantly across markers during rehearsals.","<strong>The Arrangement Loop (<code>Ctrl+L</code>):</strong> Select any clip or time range and press <code>Ctrl+L</code>. The blue Loop Brace encapsulates the selection, and the global Loop button enables."],"ordered":false}]}],"minutes":8},{"id":"ableton-l4-1-2","title":"4.1.2: Clip Manipulation, Fades & The Editing Grid","blocks":[{"type":"step","title":"4.1.2: Clip Manipulation, Fades & The Editing Grid","blocks":[{"type":"heading","text":"2.1 Clip Geometry Operations","level":4},{"type":"list","items":["<strong>Trimming / Resizing:</strong> Hover over the left or right bottom edge of a clip (half-bracket cursor appears) and drag to expand or truncate clip boundaries.","<strong>Duplication (<code>Ctrl+D</code>):</strong> Duplicates the selected clip or time selection immediately to the right.","<strong>Splitting Clips (<code>Ctrl+E</code>):</strong> Places the insert marker at a specific grid point and splits the clip into two independent objects.","<strong>Consolidation (<code>Ctrl+J</code>):</strong> Renders the selected audio fragments or MIDI notes into a single new consolidated clip file."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                          CLIP BOUNDARY &amp; FADE TOPOLOGY                      │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [CLIP A]                                    [CLIP B]                       │\n│  ─────────────┐                                ┌─────────────               │\n│               │ \\                            / │                            │\n│               │   \\  CROSSFADE OVERLAP ZONE /  │                            │\n│               │     \\                      /   │                            │\n│               │       \\                  /     │                            │\n│               │         \\              /       │                            │\n│  ─────────────┴───────────\\──────────/─────────┴─────────────               │\n│               ◄────── Fade In / Fade Out ─────►                             │\n│  (Eliminates zero-crossing clicks and ensures smooth boundary transitions) │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"heading","text":"2.2 Fades and Crossfades","level":4},{"type":"list","items":["<strong>Clip Edge Fades:</strong> Hover over the top-left or top-right corner of an audio clip (fade handle appears) and drag inward to create logarithmic or exponential volume ramps.","<strong>Crossfades:</strong> Drag the boundary of two adjoining audio clips across one another to generate automatic equal-power crossfades, eliminating phase clicks at non-zero-crossing boundaries."],"ordered":false},{"type":"heading","text":"2.3 The Editing Grid Modes","level":4},{"type":"table","headers":["Shortcut","Grid Mode / Resolution","Operational Purpose"],"rows":[["<code>Ctrl+1</code>","<strong>Narrow Grid</strong>","Increases grid division resolution (e.g., from 1/4 to 1/8 to 1/16 to 1/32)."],["<code>Ctrl+2</code>","<strong>Widen Grid</strong>","Decreases grid division resolution."],["<code>Ctrl+3</code>","<strong>Triplet Grid (Toggle)</strong>","Converts the active grid division into a triplet division (1/8T, 1/16T)."],["<code>Ctrl+4</code>","<strong>Grid Snapping (Toggle)</strong>","Disables/Enables grid snapping for freehand sample micro-positioning."],["<code>Alt</code> (Hold)","<strong>Momentary Grid Bypass</strong>","Temporarily bypasses grid snap while dragging clip edges or markers."]],"caption":null}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Timeline Navigation &amp; Zoom Drill:</strong>","Open your recorded Arrangement Set from Section 3.4.","Click in the Beat Ruler and drag down to zoom deep into a single snare drum transient.","Press <code>Z</code> on a 4-bar region; confirm instant fill-screen zoom. Press <code>Shift+Z</code> to zoom out to the full song.","Press <code>F</code> to enable Follow Playhead. Start playback and verify smooth tracking across the timeline.","<strong>Locator &amp; Loop Structure Configuration:</strong>","Navigate to bar <code>1.1.1</code>. Click <strong>Set</strong> to insert a locator. Press <code>Ctrl+R</code> and name it <code>Intro</code>.","Navigate to bar <code>9.1.1</code>. Insert a locator named <code>Verse</code>.","Navigate to bar <code>17.1.1</code>. Insert a locator named <code>Chorus</code>.","Select bars <code>9.1</code> to <code>17.1</code> on the ruler and press <code>Ctrl+L</code>. Start playback and verify infinite looping of the Verse section.","<strong>Clip Editing &amp; Crossfade Protocol:</strong>","On an audio vocal or drum track, place the edit cursor at bar <code>11.3.1</code> and press <code>Ctrl+E</code> to split the clip.","Drag the second half of the clip two beats to the right.","Pull the fade handles on both clip edges inward by 10 milliseconds. Audition the boundary to verify click-free playback."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 4.0]\n[ ] Fluent with zoom shortcuts (+, -, Z, Shift+Z, and Beat Ruler drag).\n[ ] Placed and named at least three structural Locators (Intro, Verse, Chorus).\n[ ] Set and engaged the Arrangement Loop Brace with Ctrl+L.\n[ ] Executed clip splitting (Ctrl+E), duplication (Ctrl+D), and consolidation (Ctrl+J).\n[ ] Created smooth, click-free audio fades and crossfades.\n[ ] Toggled grid snapping and triplet modes using Ctrl+1, 2, 3, 4.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 6 (<em>Arrangement View: 6.1 Navigation, 6.2 Transport, 6.3 Locators, 6.4 The Arrangement Loop, 6.7 Moving and Resizing Clips, 6.8 Audio Clip Fades and Crossfades, 6.9 Using the Editing Grid</em>).","<strong>Ableton Knowledgebase:</strong> <em>Arrangement View Editing Tips</em>, <em>Working with Locators and Song Structure</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"ableton-m-4-2-3","code":"4.2","title":"Arrangement View as a Timeline","blurb":"- Section ID: ableton-sec-4-2 - Lessons Included: ableton-l4-2-1, ableton-l4-2-2, ableton-l4-2-3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-l4-2-1","title":"Section overview","blocks":[{"type":"step","title":"Section 4.2 — Editing Time, Linked-Track Editing & The Arrangement Mixer","blocks":[{"type":"heading","text":"Metadata & Overview","level":3},{"type":"list","items":["<strong>Section ID:</strong> <code>ableton-sec-4-2</code>","<strong>Lessons Included:</strong> <code>ableton-l4-2-1</code>, <code>ableton-l4-2-2</code>, <code>ableton-l4-2-3</code>","<strong>Target Skill Band:</strong> Advanced Structural Editing &amp; Multitrack Phase Alignment","<strong>Manual Spine References:</strong> Chapter 6 (<em>Arrangement View: 6.11–6.15</em>), Chapter 18 (<em>Mixing Overview</em>)","<strong>Studio Scope Lock:</strong> Live 12 Standard (Linked-Track Multitrack Architecture)"],"ordered":false},{"type":"heading","text":"Learning Objectives","level":3},{"type":"prose","html":"Upon completing this section, the student will be able to:"},{"type":"list","items":["<strong>Execute Global Time Modification Commands:</strong> Apply <strong>Insert Silence</strong> (<code>Ctrl+I</code>), <strong>Cut Time</strong> (<code>Ctrl+Shift+X</code>), <strong>Duplicate Time</strong> (<code>Ctrl+Shift+D</code>), and <strong>Delete Time</strong> (<code>Ctrl+Shift+Del</code>) to re-structure song arrangements globally without manual clip repositioning.","<strong>Implement Phase-Aligned Linked-Track Editing:</strong> Link multiple audio/MIDI tracks into a unified editing group, executing simultaneous splits, trims, and time modifications across all members to preserve acoustic phase coherence.","<strong>Operate the Integrated Arrangement Mixer:</strong> Navigate track faders, pan controls, send knobs, solo/mute buttons, and track meters directly within the horizontal Arrangement timeline."],"ordered":true}]}],"minutes":8},{"id":"ableton-l4-2-1-2","title":"4.2.1: The Global \"...Time\" Commands","blocks":[{"type":"step","title":"1.1 Structural Arrangement Restructuring","blocks":[{"type":"prose","html":"In complex multi-track arrangements containing dozens of tracks, manually shifting clips to insert a new 8-bar chorus or delete an unwanted bridge frequently introduces timing errors. Live provides dedicated <strong>Global Time Commands</strong> that manipulate the entire horizontal timeline across all tracks simultaneously:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                         GLOBAL TIME COMMANDS MATRIX                         │\n├───────────────────┬───────────────────┬─────────────────────────────────────┤\n│ COMMAND           │ KEYBOARD SHORTCUT │ OPERATIONAL TIMELINE BEHAVIOR       │\n├───────────────────┼───────────────────┼─────────────────────────────────────┤\n│ Cut Time          │ Ctrl+Shift+X      │ Cuts the selected time range across │\n│                   │                   │ all tracks and places on clipboard; │\n│                   │                   │ shifts subsequent material left.    │\n├───────────────────┼───────────────────┼─────────────────────────────────────┤\n│ Delete Time       │ Ctrl+Shift+Del    │ Deletes selected time range across  │\n│                   │                   │ all tracks; shifts material left.   │\n├───────────────────┼───────────────────┼─────────────────────────────────────┤\n│ Duplicate Time    │ Ctrl+Shift+D      │ Duplicates selected time range and  │\n│                   │                   │ pastes immediately to the right,    │\n│                   │                   │ rippling existing material right.   │\n├───────────────────┼───────────────────┼─────────────────────────────────────┤\n│ Insert Silence    │ Ctrl+I            │ Opens dialogue to insert specified  │\n│                   │                   │ bars/beats of empty time at cursor; │\n│                   │                   │ shifts subsequent material right.   │\n└───────────────────┴───────────────────┴─────────────────────────────────────┘</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                    INSERT SILENCE &amp; DUPLICATE TIME DYNAMICS                 │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  BEFORE: [Verse (Bars 1-8)] [Chorus (Bars 9-16)]                            │\n│                                                                             │\n│  EXECUTE: Insert Silence (4 Bars at Bar 9.1)                                │\n│  AFTER:  [Verse (Bars 1-8)] [SILENCE (9-12)] [Chorus (Bars 13-20)]          │\n│          ▲                                   ▲                              │\n│          └─ Unchanged                        └── Shifted 4 bars to right    │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"ableton-l4-2-2","title":"4.2.2: Linked-Track Editing","blocks":[{"type":"step","title":"2.1 The Multitrack Phase Coherence Imperative","blocks":[{"type":"prose","html":"When editing multitrack recordings (such as acoustic drum kits tracked across 8 microphones, or layered kick and sub-bass synths), making an edit on one track without identically altering adjoining tracks destroys acoustic phase relationships:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                     LINKED-TRACK EDITING TOPOLOGY                           │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  SELECTED TRACKS: [Kick Mic] + [Snare Mic] + [Overhead L] + [Overhead R]    │\n│                                                                             │\n│  1. RIGHT-CLICK HEADERS ──► Select \"Link Tracks\" (Link Icon 🔗 Appears)     │\n│                                                                             │\n│  2. PERFORM EDIT (e.g. Trim transient at bar 4.2.1 on Kick track)           │\n│     │                                                                       │\n│     ├──► Kick Mic:    Trimmed exactly at 4.2.1                              │\n│     ├──► Snare Mic:   Trimmed identically at 4.2.1 (Phase preserved)       │\n│     ├──► Overhead L:  Trimmed identically at 4.2.1 (Phase preserved)       │\n│     └──► Overhead R:  Trimmed identically at 4.2.1 (Phase preserved)       │\n│                                                                             │\n│  3. INDIVIDUAL TWEAK   ──► Select \"Unlink Tracks\" to adjust single track.   │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Feature Availability:</strong> Linked-Track Editing is standard in <strong>Live 12 Standard</strong> (not available in Live Intro).","<strong>Rule of Hygiene:</strong> Link tracks when editing macroscopic structure, song arrangement, and rhythmic pocket; unlink tracks when applying single-instrument sound design or micro-fades."],"ordered":false}]}],"minutes":8},{"id":"ableton-l4-2-3","title":"4.2.3: The Integrated Arrangement Mixer","blocks":[{"type":"step","title":"4.2.3: The Integrated Arrangement Mixer","blocks":[{"type":"heading","text":"3.1 Unification of Mixer Controls Across Views","level":4},{"type":"prose","html":"Ableton Live does not feature two distinct mixers; the Arrangement Mixer and Session Mixer represent the same audio engine parameters viewed from different orientations:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                        ARRANGEMENT TRACK HEADER MIXER                       │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [ Track 1: Bass ] ── [ Mute/Act (1) ] [ Solo (S) ] [ Arm (●) ]             │\n│  [ In / Auto / Off]   [ Volume: -4.5 dB ] [ Pan: &lt; C &gt; ]                    │\n│  [ Sends: A: -12dB | B: -inf ] [ Output: Master ]                           │\n│  [ Track Delay: 0.00 ms ] [ Performance Impact Meter: Low ]                 │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Fader Resolution:</strong> Drag faders vertically for coarse volume adjustments; hold <code>Shift</code> while dragging for fine 0.1 dB increments; double-click to reset to unity (<code>0.0 dB</code>).","<strong>Peak Level Meters:</strong> Display instantaneous peak audio amplitude in dBFS. Orange clipping indicators light up when signal levels exceed <code>0.0 dBFS</code>."],"ordered":false}]},{"type":"step","title":"Step-by-Step Practical Application (\"In Live\")","blocks":[{"type":"list","items":["<strong>Global Arrangement Restructuring Drill:</strong>","Open your multi-track Arrangement Set.","Select bars <code>1.1</code> to <code>9.1</code> on the Beat Ruler (the 8-bar Intro).","Press <code>Ctrl+Shift+D</code> (<strong>Duplicate Time</strong>).","Verify that an exact 8-bar duplicate of the Intro is inserted, pushing the subsequent Verse cleanly to bar <code>17.1</code>.","Select bars <code>9.1</code> to <code>13.1</code> (4 bars) and press <code>Ctrl+Shift+Del</code> (<strong>Delete Time</strong>).","Verify that 4 bars are cleanly removed from the entire timeline across all tracks.","<strong>Linked-Track Multitrack Editing Protocol:</strong>","Select Track 1 (<code>Drums</code>) and Track 2 (<code>Bass</code>) by holding <code>Ctrl</code> and clicking both track headers.","Right-click the track headers and select <strong>Link Tracks</strong>. A link chain icon (<code>🔗</code>) appears on both headers.","Select bar <code>5.1</code> to <code>7.1</code> on Track 1 and press <code>Ctrl+E</code> to split.","Observe that Track 2 was split at the exact same time markers simultaneously.","Right-click track headers and select <strong>Unlink Tracks</strong> when finished.","<strong>Arrangement Level Balancing:</strong>","Set the master playhead to bar <code>17.1</code> (Chorus).","Adjust track faders in the Arrangement track headers:","Kick/Drums: <code>-3.0 dB</code>","Bass: <code>-6.0 dB</code>","Synths: <code>-8.0 dB</code>","Press <code>Tab</code> to switch to Session View. Confirm that all fader positions in the vertical Session mixer match the exact values entered in Arrangement View."],"ordered":true}]},{"type":"step","title":"Self-Assessment & Verification Checkpoint","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[VERIFICATION CHECKLIST: MODULE 4.1]\n[ ] Successfully executed Duplicate Time (Ctrl+Shift+D) and Delete Time (Ctrl+Shift+Del).\n[ ] Linked two or more tracks and executed simultaneous, phase-aligned splits.\n[ ] Unlinked tracks to restore independent editing capability.\n[ ] Verified that Arrangement mixer adjustments reflect identically in Session View.</pre>"}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 6 (<em>Arrangement View: 6.11 Using the ...Time Commands, 6.14 Linked-Track Editing, 6.15 The Arrangement Mixer</em>), Chapter 18 (<em>Mixing</em>).","<strong>Ableton Knowledgebase:</strong> <em>Linked-Track Editing in Live</em>, <em>Using Time Commands to Restructure Arrangements</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
